<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['admin','manager']); $db=db(); $user=(int)($_GET['user_id']??0); $action=trim($_GET['action']??''); $from=trim($_GET['from']??''); $to=trim($_GET['to']??''); $where=[];$args=[]; if($user){$where[]='a.user_id=?';$args[]=$user;} if($action!==''){$where[]='a.action=?';$args[]=$action;} if($from!==''){$where[]='a.created_at>=?';$args[]=$from.' 00:00:00';} if($to!==''){$where[]='a.created_at<=?';$args[]=$to.' 23:59:59';} $sql='SELECT a.*,COALESCE(u.username,"System") username,COALESCE(u.role,"system") role FROM audit_log a LEFT JOIN users u ON u.id=a.user_id'; if($where)$sql.=' WHERE '.implode(' AND ',$where); $sql.=' ORDER BY a.id DESC LIMIT 300'; $st=$db->prepare($sql);$st->execute($args);$rows=$st->fetchAll(); $users=$db->query('SELECT id,username FROM users ORDER BY username')->fetchAll(); $actions=$db->query('SELECT DISTINCT action FROM audit_log WHERE action<>"" ORDER BY action')->fetchAll(PDO::FETCH_COLUMN); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activity Log</title><link rel="stylesheet" href="style.css"><style>.filters{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;gap:10px;align-items:end}.filters label{font-size:12px;font-weight:700;color:#475569}.filters select,.filters input{margin-top:5px}.role{font-size:11px;color:#64748b}.action{font-weight:700}.meta{font-size:11px;color:#64748b;max-width:420px;word-break:break-word}@media(max-width:900px){.filters{grid-template-columns:1fr 1fr}.filters .btn{grid-column:1/-1}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="index.php?action=medicines">Medicines</a><a href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">SECURITY & ACCOUNTABILITY</div><h1>Activity Log</h1><p>See who performed sales, purchases, returns, expenses and cash operations.</p></div></div><section class="panel"><form class="filters" method="get"><label>User<select name="user_id"><option value="">All users</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=$user===(int)$u['id']?'selected':''?>><?=e($u['username'])?></option><?php endforeach;?></select></label><label>Action<select name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option value="<?=e($a)?>" <?=$action===$a?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Filter</button></form></section><section class="panel"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><h2>Recent activity</h2><small>Showing up to 300 entries</small></div><a class="btn" href="audit.php">Clear filters</a></div><table><tr><th>Date & Time</th><th>User</th><th>Role</th><th>Action</th><th>Details</th></tr><?php if(!$rows):?><tr><td colspan="5">No activity found.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><b><?=e($r['username'])?></b></td><td><span class="role"><?=e($r['role'])?></span></td><td><span class="action"><?=e($r['action'])?></span></td><td class="meta"><?=e((string)($r['details']??''))?></td></tr><?php endforeach;endif;?></table></section></main></body></html>